# $wordToComplete : the token currently being typed (may be empty if cursor is after a space)
# $commandAst     : the full parsed command AST; .CommandElements is the token array
# $cursorPosition : byte offset of the cursor in the command string
Register-ArgumentCompleter -Native -CommandName $_CDS_COMMAND -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $map = $_CDS_COMPLETIONS
    $cmdSegments = $commandAst.CommandElements
    if ($null -eq $wordToComplete) { $wordToComplete = '' }

    # Helper: emit file/dir completions for a sentinel value.
    # Sentinel formats: ':file' (any file), ':dir' (directories only),
    #                   ':file:ext1,ext2' (files with specific extensions).
    # Uses relative paths (preserving any typed prefix) so the completed text stays short.
    function _CdsFileComplete($sentinel, $word) {
        $base   = if ($word) { $word } else { '' }
        $search = if ($word) { "$word*" } else { '*' }
        # Parse extension list from ':file:cds,json' → @('.cds', '.json')
        $exts = if ($sentinel -like ':file:*') {
            ($sentinel -replace '^:file:', '').Split(',') | ForEach-Object { ".$_" }
        } else { $null }
        if ($sentinel -eq ':dir') {
            Get-ChildItem -Path $search -Directory -ErrorAction SilentlyContinue |
                ForEach-Object {
                    $rel = $base + $_.Name
                    [System.Management.Automation.CompletionResult]::new($rel, $_.Name, 'ProviderItem', $_.Name)
                }
        } else {
            Get-ChildItem -Path $search -File -ErrorAction SilentlyContinue |
                Where-Object { $null -eq $exts -or $exts -contains $_.Extension } |
                ForEach-Object {
                    $rel = $base + $_.Name
                    [System.Management.Automation.CompletionResult]::new($rel, $_.Name, 'ProviderItem', $_.Name)
                }
        }
    }

    # Step 1: top-level command completion — cursor is on the subcommand token itself.
    # Either no subcommand yet (count=1) or the user is still typing it (count=2, partial match).
    $isTopLevel = $cmdSegments.Count -eq 1 -or ($cmdSegments.Count -eq 2 -and $wordToComplete -ne '' -and $cmdSegments[1].Extent.Text -eq $wordToComplete)
    if ($isTopLevel) {
        foreach ($cmd in $map['__commands']) {
            if ($cmd.StartsWith($wordToComplete)) {
                [System.Management.Automation.CompletionResult]::new($cmd, $cmd, 'ParameterValue', $cmd)
            }
        }
        return
    }

    # Step 2: resolve shortcut to canonical command name so the rest of the
    # logic only needs to handle canonical names.
    $subCmd = $cmdSegments[1].Extent.Text
    $resolved = $map['__shortcuts'][$subCmd]
    if ($null -ne $resolved) { $subCmd = $resolved }

    # Compute $previousWord — the token immediately before the cursor.
    # When $wordToComplete is empty the cursor is after a space, so the last completed
    # token is the previous word. When non-empty the cursor is mid-token, so look one
    # further back. EndOffset filtering keeps only tokens that end before the cursor.
    $prevCandidates = $cmdSegments | Where-Object { $_.Extent.EndOffset -le $cursorPosition }
    $previousWord = if ($wordToComplete -eq '') {
        ($prevCandidates | Select-Object -Last 1).Extent.Text
    } else {
        ($prevCandidates | Select-Object -Last 2 | Select-Object -First 1).Extent.Text
    }

    # Step 3: flag/option completion — triggered when $wordToComplete starts with '-'.
    if ($wordToComplete.StartsWith('-')) {
        $entry = $map[$subCmd]
        if ($null -ne $entry) {
            foreach ($opt in $entry) {
                if ($opt.StartsWith($wordToComplete)) {
                    [System.Management.Automation.CompletionResult]::new($opt, $opt, 'ParameterValue', $opt)
                }
            }
            return
        }
    }

    # Step 3.5: option-value completion — triggered when the previous word is a known option.
    $optVals = $map['__optionValues'][$subCmd]
    if ($null -ne $optVals) {
        $entry = $optVals[$previousWord]
        if ($null -ne $entry) {
            if ($entry -eq ':dir' -or $entry -eq ':file' -or $entry -like ':file:*') {
                _CdsFileComplete $entry $wordToComplete
            } else {
                foreach ($val in $entry) {
                    if ($val.StartsWith($wordToComplete)) {
                        [System.Management.Automation.CompletionResult]::new($val, $val, 'ParameterValue', $val)
                    }
                }
            }
            return
        }
    }

    # Step 3.6: comma-separated option-value completion.
    $commaVals = $map['__commaCases'][$subCmd]
    if ($null -ne $commaVals) {
        # Primary lookup: previous word is the option flag (e.g. '--add').
        $entry = $commaVals[$previousWord]
        if ($null -eq $entry -and $previousWord.EndsWith(',')) {
            # Space-separated continuation: user typed "cds add ai, <tab>" so $previousWord="ai,"
            # and $wordToComplete is empty. Scan backwards through segments to find the flag.
            $prevSegs = @($cmdSegments | ForEach-Object { $_.Extent.Text })
            $prevIdx = [array]::LastIndexOf($prevSegs, $previousWord) - 1
            while ($prevIdx -ge 0 -and -not $prevSegs[$prevIdx].StartsWith('-')) { $prevIdx-- }
            if ($prevIdx -ge 0) { $entry = $commaVals[$prevSegs[$prevIdx]] }
        }
        # Positional fallback: previous word is not a flag (it's the subcommand or a value).
        if ($null -eq $entry -and -not $previousWord.StartsWith('-')) {
            $entry = $commaVals['_']
        }
        if ($null -ne $entry) {
            # For space-separated comma continuation, fold previousWord into the prefix/alreadyUsed.
            $spaceComma = $previousWord.EndsWith(',')
            $commaWord = if ($spaceComma) { $previousWord + $wordToComplete } else { $wordToComplete }
            $parts = $commaWord.Split(',')
            $prefix = if ($parts.Count -gt 1) { ($parts[0..($parts.Count-2)] -join ',') + ',' } else { '' }
            $partial = $parts[-1]
            $alreadyUsed = @{}
            foreach ($u in $parts[0..($parts.Count-2)]) { if ($u) { $alreadyUsed[$u] = $true } }
            foreach ($val in $entry) {
                if (-not $alreadyUsed.ContainsKey($val) -and $val.StartsWith($partial)) {
                    # When space-separated (prev="ai,"), PS replaces only $wordToComplete (=''),
                    # so return just $val — the prefix is already on the line.
                    $full = if ($spaceComma) { $val } else { $prefix + $val }
                    [System.Management.Automation.CompletionResult]::new($full, $val, 'ParameterValue', $val)
                }
            }
            return
        }
    }

    # Step 4: static string positionals (e.g. cds help <tab>).
    $positionals = $map['__positionals'][$subCmd]
    if ($null -ne $positionals) {
        $matched = $false
        foreach ($pos in $positionals) {
            if ($pos.StartsWith($wordToComplete)) {
                [System.Management.Automation.CompletionResult]::new($pos, $pos, 'ParameterValue', $pos)
                $matched = $true
            }
        }
        if ($matched) { return }
    }

    # Step 4.5: default file sentinel — files only, no flags appended.
    $defaultFile = $map['__optionValues'][$subCmd]?['_']
    if ($null -ne $defaultFile) {
        _CdsFileComplete $defaultFile $wordToComplete
        return
    }

    # Step 5: dynamic fallback — calls 'cds completion' for subcommands whose arguments
    # cannot be determined statically (e.g. service names, model names, unknown flags).
    # Single-quoting $previousWord/$wordToComplete prevents bare word 'h' from being
    # interpreted as the 'help' shortcut by the completion handler.
    $options = & $_CDS_COMMAND completion --shell ps --prev "'$previousWord'" --curr "'$wordToComplete'" --line "'$commandAst'"
    foreach ($option in $options) {
        [System.Management.Automation.CompletionResult]::new($option, $option, 'ParameterValue', $option)
    }
}
